inner="\nfrom pathlib import Path\nimport json,sys,numpy as np,torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,*_=models;cache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\n# All records used by the channel-estimator pilot, including its source\n# validation and holdout, are excluded; other earlier source probes may overlap.\nold_rng=np.random.default_rng(2026110351);new_rng=np.random.default_rng(2026110361);groups=[]\nfor role,old_count,take in (('L_s',512,2048),('U_s',1536,6144)):\n available=np.flatnonzero(roles==role);previous=old_rng.choice(available,size=old_count,replace=False)\n available=np.setdiff1d(available,np.sort(previous),assume_unique=True);groups.append(np.sort(new_rng.choice(available,size=take,replace=False)))\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==8192\nsource_rx=rx[fixed];source_day=day[fixed];split=np.full(len(fixed),-1,dtype=np.int64)\nsplit[np.isin(source_rx,[1,3,4])&np.isin(source_day,[1,2])]=0;split[np.isin(source_rx,[4,6])&(source_day==3)]=1;split[(source_rx==8)&(source_day==3)]=2\nkeep=split>0;fixed=fixed[keep];source_rx=source_rx[keep];source_day=source_day[keep];split=split[keep];assert len(fixed)>300\nviews=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');namespace='phase1-source-channel-clean-guard-2026110362';data={}\nwith torch.no_grad():\n for view in views:\n  if view=='clean':received=np.asarray(clean[fixed],dtype=np.float32)\n  else:\n   cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect');received=[]\n   for j in fixed:\n    pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110363,session)\n    v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110362,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  anchors=[];rawp=[];basep=[]\n  for start in range(0,len(fixed),32):\n   x=core.tensor(received[start:start+32],'cpu');a=dura(x);anchors.append(a.cpu());rawp.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu());basep.append(F.softmax(teacher.classify_features(teacher.features(a)),1).cpu())\n  x=core.tensor(received,'cpu');anchors=torch.cat(anchors);rms=x.square().sum(1).mean(1).sqrt().clamp_min(1e-8)\n  data[view]=dict(x=torch.cat((x/rms[:,None,None],anchors/rms[:,None,None]),1),log_rms=rms.log()[:,None],rawp=np.from_dlpack(torch.cat(rawp).contiguous()),basep=np.from_dlpack(torch.cat(basep).contiguous()))\n  print('ESTIMATED_CHANNEL_SOURCE_BASELINES_FIXED',view,flush=True)\nclass ChannelNet(nn.Module):\n def __init__(self):\n  super().__init__();self.net=nn.Sequential(nn.Conv1d(4,32,7,stride=2,padding=3),nn.GELU(),nn.Conv1d(32,64,5,stride=2,padding=2),nn.GELU(),nn.Conv1d(64,64,3,stride=2,padding=1),nn.GELU(),nn.AdaptiveAvgPool1d(1));self.head=nn.Sequential(nn.Linear(65,128),nn.GELU(),nn.Linear(128,126))\n def forward(self,x,amp):return self.head(torch.cat((self.net(x).squeeze(-1),amp),1))\n\nexpected=json.load(sys.stdin);net=ChannelNet();net.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in expected['model_state'].items()},strict=True);net.eval()\nfactors=(10.,);gate_scales=(0.,.02,.05,.1,.2);predictions={};candidate_waves={};baseline_waves={}\nwith torch.no_grad():\n for view in views:\n  estimated=[]\n  for start in range(0,len(fixed),64):estimated.append(net(data[view]['x'][start:start+64],data[view]['log_rms'][start:start+64]).cpu())\n  estimated=np.from_dlpack(torch.cat(estimated).contiguous());inputs=np.from_dlpack(data[view]['x'].contiguous());candidate=[[] for _ in range(1+len(factors))]\n  for j in range(len(fixed)):\n   y=inputs[j,0].astype(np.float64)+1j*inputs[j,1];prior=inputs[j,2].astype(np.float64)+1j*inputs[j,3]\n   h=(estimated[j,:62].astype(np.float64)+1j*estimated[j,62:124])*np.exp(float(estimated[j,124]));freq=float(estimated[j,125])*10000.\n   assert np.isfinite(h).all() and np.isfinite(freq);n=len(y);m=len(h);t=np.arange(n)/25e6;y0=y*np.exp(-2j*np.pi*freq*t)\n   idx=np.pad(np.arange(n),(m-1,0),mode='reflect');columns=idx[np.arange(n)[:,None]+m-1-np.arange(m)[None,:]];H=np.zeros((n,n),dtype=np.complex128)\n   np.add.at(H,(np.arange(n)[:,None],columns),np.broadcast_to(h,(n,m)))\n   padded=np.pad(prior,(16,16),mode='reflect');shifts=np.stack([padded[16+s:16+s+n] for s in range(-16,17)],axis=1);forward=H@shifts\n   gain=(forward.conj()*y0[:,None]).sum(0)/np.maximum((abs(forward)**2).sum(0),1e-20);residual=y0[:,None]-forward*gain[None,:];jbest=int(np.argmin(np.mean(abs(residual)**2,axis=0)))\n   p=shifts[:,jbest]*gain[jbest];candidate[0].append(np.stack((p.real,p.imag)).astype(np.float32))\n   noise=max(float(np.mean(abs(residual[:,jbest])**2)),1e-12);power=max(float(np.mean(abs(p)**2)),1e-12)\n   eig,V=np.linalg.eigh(H.conj().T@H);rhs=V.conj().T@(H.conj().T@y0);pv=V.conj().T@p\n   for k,factor in enumerate(factors):\n    reg=factor*noise/power;z=V@((rhs+reg*pv)/(np.maximum(eig,0)+reg));assert np.isfinite(z).all();candidate[k+1].append(np.stack((z.real,z.imag)).astype(np.float32))\n  candidate=[np.stack(x) for x in candidate];aligned=[]\n  # Align each candidate to DURA using only the candidate and DURA. This is\n  # a per-record, label-free shift/gain fit; the paired clean source is unused.\n  for wave in candidate[1:]:\n   aligned_wave=[]\n   for j in range(len(fixed)):\n    z=wave[j,0].astype(np.float64)+1j*wave[j,1];a=inputs[j,2].astype(np.float64)+1j*inputs[j,3]\n    padded=np.pad(z,(16,16),mode='reflect');crop=a[16:-16];best_fit=None\n    for shift in range(-16,17):\n     full=padded[16+shift:16+shift+len(a)];part=full[16:-16];gain=np.vdot(part,crop)/max(float(np.vdot(part,part).real),1e-20)\n     mse=float(np.mean(abs(gain*part-crop)**2))\n     if best_fit is None or mse<best_fit[0]:best_fit=(mse,gain*full)\n    aligned_wave.append(best_fit[1])\n   aligned.append(np.stack(aligned_wave))\n  anchor=inputs[:,2,:].astype(np.float64)+1j*inputs[:,3,:];received=inputs[:,0,:].astype(np.float64)+1j*inputs[:,1,:]\n  rms=np.exp(np.from_dlpack(data[view]['log_rms'].contiguous()).reshape(-1));relative=np.sqrt(np.mean(abs(received-anchor)**2,axis=1)/np.maximum(np.mean(abs(received)**2,axis=1),1e-12));fused=[]\n  baseline=anchor*rms[:,None];baseline_waves[view]=np.stack((baseline.real,baseline.imag),axis=1).astype(np.float32)\n  for scale in gate_scales:\n   gate=np.ones(len(fixed)) if scale==0 else np.clip(relative/scale,0,1)\n   z=(anchor+.5*gate[:,None]*(aligned[0]-anchor))*rms[:,None];assert np.isfinite(z).all();fused.append(np.stack((z.real,z.imag),axis=1).astype(np.float32))\n  candidate=fused;candidate_waves[view]=candidate;parts=[]\n  for start in range(0,len(fixed),32):\n   inputs=[core.tensor(x[start:start+32],'cpu') for x in candidate];parts.append(torch.stack([teacher.classify_features(teacher.features(x)).argmax(1) for x in inputs],1).cpu())\n  predictions[view]=np.from_dlpack(torch.cat(parts).contiguous());print('ESTIMATED_CHANNEL_SOURCE_CANDIDATES_FIXED',view,flush=True)\nprint('ALL_ESTIMATED_CHANNEL_SOURCE_CANDIDATES_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1)\nref=data['clean']['rawp'];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_target)\ndef evaluate(which,part,group=None):\n mask=(split==part)&valid;cm=split==part\n if group is not None:mask &= source_rx==group;cm &= source_rx==group\n per={};clean_net=0\n for view in views:\n  pred=predictions[view][:,which];base=data[view]['basep'].argmax(1);old=base==target;new=pred==target;lm=mask&labeled\n  per[view]=dict(valid_count=int(mask.sum()),L_s_count=int(lm.sum()),U_confident_count=int((mask&~labeled).sum()),baseline=int((mask&old).sum()),student=int((mask&new).sum()),repairs=int((mask&~old&new).sum()),damages=int((mask&old&~new).sum()),L_s_baseline=int((lm&old).sum()),L_s_student=int((lm&new).sum()))\n  if view=='clean':clean_net=int((cm&(pred==teacher_target)).sum()-(cm&(base==teacher_target)).sum())\n return per,clean_net\nvalidation=[];best={'kind':'dura','validation_net':0}\nfor which in range(len(gate_scales)):\n per,clean_net=evaluate(which,1);changes={v:per[v]['student']-per[v]['baseline'] for v in views[1:]};net_gain=sum(changes.values());groups_v={}\n for group in (4,6):\n  gp,gclean=evaluate(which,1,group);count=int(((split==1)&(source_rx==group)).sum());gc={v:gp[v]['student']-gp[v]['baseline'] for v in views[1:]};groups_v[str(group)]=dict(n=count,net=sum(gc.values()),per_view=gc,clean_teacher_net=gclean)\n validation.append(dict(candidate=which,net=net_gain,per_view=changes,clean_teacher_net=clean_net,groups=groups_v))\n guards=all(z['net']>=0 and z['clean_teacher_net']>=-.01*z['n'] and min(z['per_view'].values())>=-.005*z['n'] for z in groups_v.values())\n if net_gain>best['validation_net'] and guards:best=dict(kind='clean_guarded_channel_fusion',candidate=which,validation_net=net_gain)\nif best['kind']=='dura':heldout=None;clean_net=None;quality=None\nelse:\n heldout,clean_net=evaluate(best['candidate'],2);quality={};mask=split==2;reference=core.tensor(np.asarray(clean[fixed[mask]],dtype=np.float32),'cpu')\n def as_complex(z):return torch.complex(z[:,0,:],z[:,1,:])\n def aligned_mse(signal,target,maxshift=16):\n  crop=target[:,maxshift:-maxshift];errors=[]\n  for shift in range(-maxshift,maxshift+1):\n   seg=signal[:,maxshift+shift:signal.shape[1]-maxshift+shift];gain=(seg.conj()*crop).sum(1)/seg.abs().square().sum(1).clamp_min(1e-12)\n   errors.append((gain[:,None]*seg-crop).abs().square().mean(1))\n  return torch.stack(errors,1).min(1).values\n for view in views:\n  base=core.tensor(baseline_waves[view][mask],'cpu');wave=core.tensor(candidate_waves[view][best['candidate']][mask],'cpu')\n  before=aligned_mse(as_complex(base),as_complex(reference));after=aligned_mse(as_complex(wave),as_complex(reference))\n  quality[view]=dict(count=int(mask.sum()),aligned_mse_before=float(before.mean()),aligned_mse_after=float(after.mean()),improved=int((after<before).sum()),worsened=int((after>before).sum()))\ncontrol,control_clean=evaluate(0,2)\nprint('SOURCE_CLEAN_GUARDED_CHANNEL_PROBE '+json.dumps(dict(status='SOURCE_ONLY_CLEAN_GUARDED_CHANNEL_PROBE',source_ids=len(fixed),validation_ids=int((split==1).sum()),heldout_ids=int((split==2).sum()),factors=list(factors),blend=.5,gate_scales=list(gate_scales),validation=validation,selected=best,heldout=heldout,heldout_clean_teacher_net=clean_net,quality=quality,ungated_control=control,ungated_control_clean=control_clean,U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='The estimated channel, prior alignment, posterior and DURA-aligned blending depend only on received IQ, fixed DURA and fixed source-trained estimator. The estimator used simulator traces during source training, not inference. Source IDs exclude the estimator pilot records but may overlap other source diagnostics; original source validation chose the estimator checkpoint; heldout receiver/day is disjoint only for estimator fitting. Frozen experts saw source records and simulator is not validated satellite data. Prior observed Phase1 test results motivated exploration.'),ensure_ascii=False),flush=True)\n"
